class Solution {
    public int majorityElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (nums[j] == nums[i]) count++;
            }
            if (count > n / 2) return nums[i];
        }
        return -1; // 题目保证有解，不会走到
    }
}

import java.util.*;

class Solution {
    public int majorityElement(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        int majority = nums[0];
        for (int x : nums) {
            int c = count.merge(x, 1, Integer::sum);
            if (c > nums.length / 2) {
                return x;
            }
        }
        return majority;
    }
}

import java.util.*;

class Solution {
    public int majorityElement(int[] nums) {
        Arrays.sort(nums);
        return nums[nums.length / 2];
    }
}

class Solution {
    public int majorityElement(int[] nums) {
        int candidate = nums[0];  // 初始候选人
        int count = 1;            // 初始计数

        for (int i = 1; i < nums.length; i++) {
            if (count == 0) {
                candidate = nums[i];  // 换人
                count = 1;
            } else if (nums[i] == candidate) {
                count++;               // 同阵营 +1
            } else {
                count--;               // 异阵营 -1（一消一抵）
            }
        }
        return candidate;
    }
}

