// 暴力思路（有隐患）
class Solution {
    public boolean isHappy(int n) {
        while (n != 1) {
            n = getSum(n);
        }
        return true;
    }
    private int getSum(int n) {
        int sum = 0;
        while (n > 0) {
            int d = n % 10;
            sum += d * d;
            n /= 10;
        }
        return sum;
    }
}

// 优化解：HashSet 检测循环，O(log n) 步、空间 O(log n)
class Solution {
    public boolean isHappy(int n) {
        Set<Integer> seen = new HashSet<>();
        while (n != 1 && !seen.contains(n)) {
            seen.add(n);
            n = getSum(n);
        }
        return n == 1;
    }
    private int getSum(int n) {
        int sum = 0;
        while (n > 0) {
            int d = n % 10;
            sum += d * d;
            n /= 10;
        }
        return sum;
    }
}

// 最优解：快慢指针判圈，时间 O(log n)、空间 O(1)
class Solution {
    public boolean isHappy(int n) {
        int slow = n, fast = getSum(n);
        while (fast != 1 && slow != fast) {
            slow = getSum(slow);
            fast = getSum(getSum(fast));
        }
        return fast == 1;
    }
    private int getSum(int n) {
        int sum = 0;
        while (n > 0) {
            int d = n % 10;
            sum += d * d;
            n /= 10;
        }
        return sum;
    }
}

