class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length, minLen = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int j = i; j < n; j++) {
                sum += nums[j];
                if (sum >= target) {
                    minLen = Math.min(minLen, j - i + 1);
                    break; // 再往右长度只会更大，当前 i 下已最优
                }
            }
        }
        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        int left = 0, sum = 0, minLen = Integer.MAX_VALUE;
        for (int right = 0; right < n; right++) {
            sum += nums[right];
            while (sum >= target) {                 // 窗口和够，尝试收缩
                minLen = Math.min(minLen, right - left + 1);
                sum -= nums[left];
                left++;
            }
        }
        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int need = prefix[i] + target;
            // 在 prefix[i+1 .. n] 中找第一个 >= need 的下标
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (prefix[mid] >= need) hi = mid;  // 左闭右开找下界
                else lo = mid + 1;
            }
            if (lo <= n && prefix[lo] >= need) {
                minLen = Math.min(minLen, lo - i);
            }
        }
        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }
}

